// ===== Configuração (preencha no seu n8n; nunca no repositório) =====
const EMISSOR = 'Escola Exemplo de Idiomas';
const URL_VALIDACAO = 'https://exemplo.com/webhook/validar';  // endereço público da validação
const MODELO_CERTIFICADO = '';  // ID do modelo no Google Slides
const MODELO_DECLARACAO = '';
// ponytail: o QR é desenhado por um serviço externo, que vê a URL de validação
// (só o ID, nenhum dado do aluno). Se precisar evitar, trocar por um gerador próprio.
const QR_API = 'https://api.qrserver.com/v1/create-qr-code/?size=600x600&margin=0&data=';
// ====================================================================

const TIPOS = {
  certificado_curso: 'Certificado de conclusão de curso',
  certificado_semestre: 'Certificado de conclusão de semestre',
  certificado_trimestre: 'Certificado de conclusão de trimestre',
  declaracao_matricula: 'Declaração de matrícula',
  declaracao_termino_semestre: 'Declaração de término de semestre',
};
const OBRIGATORIOS = {
  certificado_semestre: ['nome', 'curso', 'carga_horaria'],
  certificado_trimestre: ['nome', 'curso', 'carga_horaria'],
  declaracao_matricula: ['nome', 'curso', 'cpf', 'rg', 'endereco'],
  declaracao_termino_semestre: ['nome', 'curso', 'cpf', 'rg', 'endereco'],
};
const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho',
  'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];

const esc = v => String(v ?? '').replace(/[&<>"']/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const txt = v => String(v ?? '').trim();
const ID = /^[A-Za-z0-9]{12}$/;

function extenso(valor) {  // 'AAAA-MM-DD' ou 'DD/MM/AAAA' -> '24 de setembro de 2026', ou ''
  let m = txt(valor).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const [a, me, d] = m ? [+m[1], +m[2], +m[3]]
    : (m = txt(valor).match(/^(\d{2})\/(\d{2})\/(\d{4})$/)) ? [+m[3], +m[2], +m[1]] : [];
  const dt = new Date(Date.UTC(a, me - 1, d));
  if (!m || dt.getUTCMonth() !== me - 1 || dt.getUTCDate() !== d) return '';
  return `${d} de ${MESES[me - 1]} de ${a}`;
}

const q = $('Webhook').first().json.query || {};
const novoId = txt($('Gerar ID').first().json.novo_id).replace(/[^A-Za-z0-9]/g, '').slice(0, 12);
const entrada = $input.all().map(i => i.json);
const linhas = entrada.filter(r => r.row_number);
const contagem = {};
for (const r of linhas) contagem[txt(r.id)] = (contagem[txt(r.id)] || 0) + 1;

function problema(r) {
  if (!txt(r.id)) return '';
  if (!ID.test(txt(r.id))) return 'ID inválido';
  return contagem[txt(r.id)] > 1 ? 'ID duplicado' : '';
}

function pagina(status, erro) {
  const docs = linhas.slice().reverse().map(r => {
    const p = problema(r);
    const acao = p ? `<span class="bad">${esc(p)}</span>`
      : `<a class="btn" href="?${txt(r.id) ? 'id=' + encodeURIComponent(txt(r.id)) : 'linha=' + r.row_number}">Baixar PDF</a>`;
    return `<tr><td>${esc(r.nome)}</td><td>${esc(r.tipo_documento)}</td><td>${esc(r.curso)}</td>
      <td>${esc(r.data_emissao)}</td><td>${esc(r.status)}</td><td>${acao}</td></tr>`;
  }).join('\n');
  const html = `<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Emissão de documentos</title>
<style>
  body { margin: 0; font-family: system-ui, sans-serif; background: #f2f5f5; color: #1f2a2b; }
  header { background: #0f3d3e; color: #fff; padding: 20px 16px; }
  header h1 { margin: 0; font-size: 1.1rem; letter-spacing: .04em; }
  main { max-width: 960px; margin: 20px auto; padding: 0 16px; }
  .card { background: #fff; border-radius: 12px; padding: 16px; box-shadow: 0 1px 3px rgba(0,0,0,.08); margin-bottom: 16px; }
  h2 { font-size: 1rem; margin: 0 0 8px; }
  .muted { color: #5f6f70; font-size: .9rem; }
  .table { overflow-x: auto; }
  table { width: 100%; border-collapse: collapse; font-size: .9rem; }
  th, td { text-align: left; padding: 8px 6px; border-bottom: 1px solid #e1e9e9; white-space: nowrap; }
  a.btn { display: inline-block; padding: 6px 12px; border-radius: 6px; background: #0e7c7b; color: #fff; text-decoration: none; }
  .bad { color: #b3261e; }
</style>
</head>
<body>
<header><h1>EMISSÃO DE DOCUMENTOS${EMISSOR ? ' · ' + esc(EMISSOR) : ''}</h1></header>
<main>
  ${erro ? `<div class="card"><p class="bad"><strong>Não foi possível gerar o PDF:</strong> ${esc(erro)}</p>
  <p class="muted">Corrija o problema e tente de novo.</p></div>` : ''}
  <div class="card">
    <h2>Documentos da planilha (${linhas.length})</h2>
    <p class="muted">Os mais recentes primeiro. Linha sem ID ganha um ID novo, gravado na planilha, ao baixar o PDF.
    Para achar um aluno, use a busca do navegador.</p>
    <div class="table"><table>
      <tr><th>Nome</th><th>Documento</th><th>Curso</th><th>Emissão</th><th>Status</th><th></th></tr>
      ${docs}
    </table></div>
  </div>
</main>
</body>
</html>`;
  return [{ json: { acao: 'pagina', status, html } }];
}

if (entrada.some(r => r.error)) {  // falha ao ler a planilha: detalhe só no n8n
  return [{ json: { acao: 'pagina', status: 503, html: '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">'
    + '<title>Indisponível</title></head><body><h1>Serviço temporariamente indisponível</h1>'
    + '<p>Tente de novo em alguns minutos.</p></body></html>' } }];
}
if (!q.id && !q.linha) return pagina(200);

// Linha escolhida: pelo ID (tem de ser único) ou pelo número da linha (sem ID ainda).
let r;
if (q.id) {
  const achadas = linhas.filter(l => txt(l.id) === txt(q.id));
  if (achadas.length !== 1) return pagina(404, achadas.length ? 'ID duplicado na planilha.' : 'documento não encontrado.');
  r = achadas[0];
} else {
  r = linhas.find(l => String(l.row_number) === txt(q.linha));
  if (!r) return pagina(404, 'linha não encontrada.');
}
const erro = m => pagina(422, `${txt(r.nome) || 'linha ' + r.row_number}: ${m}`);

let id = txt(r.id);
const idNovo = !id;
if (idNovo) {
  if (!ID.test(novoId) || contagem[novoId]) return erro('falha ao gerar o ID; tente de novo.');
  id = novoId;
} else if (problema(r)) {
  return erro(problema(r));
}

const tipo = txt(r.tipo_documento);
if (tipo === 'certificado_curso') {
  // ponytail: a página do conteúdo do curso ainda não tem modelo no Slides.
  return erro('o certificado de curso completo ainda não é emitido por aqui.');
}
if (!OBRIGATORIOS[tipo]) return erro(`tipo_documento desconhecido: "${tipo}".`);
const faltando = ['data_emissao', ...OBRIGATORIOS[tipo]].filter(k => !txt(r[k]));
if (faltando.length) return erro(`campos obrigatórios ausentes: ${faltando.join(', ')}.`);
const data = extenso(r.data_emissao);
if (!data) return erro(`data_emissao inválida: "${txt(r.data_emissao)}".`);
const modelo = tipo.startsWith('certificado_') ? MODELO_CERTIFICADO : MODELO_DECLARACAO;
if (!modelo || !URL_VALIDACAO) return erro('modelo ou URL de validação não configurados no n8n.');

const curso = txt(r.curso);
const extras = [
  txt(r.dia_aula) && `com aulas semanais (${txt(r.dia_aula)})`,
  txt(r.carga_horaria) && `com carga horária de ${txt(r.carga_horaria)} horas`,
].filter(Boolean);
const textos = tipo.startsWith('certificado_') ? {
  nome: txt(r.nome),
  conclusao: tipo === 'certificado_semestre' ? 'concluiu o semestre do curso de' : 'concluiu o trimestre do curso de',
  CURSO: curso.toUpperCase(),
  carga_horaria: txt(r.carga_horaria),
} : {
  TITULO: tipo === 'declaracao_matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 'DECLARAÇÃO DE TÉRMINO DE SEMESTRE',
  abertura: tipo === 'declaracao_matricula' ? 'declara, para os fins que sejam necessários, que' : 'declara que o semestre de',
  NOME: txt(r.nome).toUpperCase(),
  cpf: txt(r.cpf),
  rg: txt(r.rg),
  ENDERECO: txt(r.endereco).toUpperCase(),
  situacao: tipo === 'declaracao_matricula' ? 'está devidamente matriculado(a) no' : 'foi concluído no',
  curso_destaque: tipo === 'declaracao_matricula' ? `curso de ${curso}` : `CURSO DE ${curso.toUpperCase()}`,
  extras: extras.length ? ', ' + extras.join(' e ') : '',
};
textos.data = data;
textos.id = id;

// Pedidos para a API do Slides: troca cada {{marcador}} e a caixa {{qr}} pela imagem.
const requests = Object.entries(textos).map(([k, v]) => ({
  replaceAllText: { containsText: { text: `{{${k}}}`, matchCase: true }, replaceText: v },
}));
requests.push({ replaceAllShapesWithImage: {
  containsText: { text: '{{qr}}', matchCase: true },
  imageUrl: QR_API + encodeURIComponent(`${URL_VALIDACAO}?id=${id}`),
  imageReplaceMethod: 'CENTER_INSIDE',
} });

// Nome do arquivo para o Content-Disposition: sem controles, aspas nem barras.
const arquivo = `${TIPOS[tipo]} - ${txt(r.nome)}`.replace(/[\u0000-\u001f\u007f-\u009f​-‏‪-‮⁦-⁩/\\"]/g, '')
  .replace(/\s+/g, ' ').trim() + '.pdf';
const ascii = arquivo.normalize('NFD').replace(/[^\x20-\x7e]/g, '');
const disposicao = `attachment; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(arquivo)
  .replace(/['()*]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase())}`;

return [{ json: { acao: 'pdf', row_number: r.row_number, id, id_novo: idNovo, modelo, copia: `Emissão ${id}`,
  arquivo, disposicao, requests } }];
